package com.nexusdrive.common.security;
import java.util.*; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails;
public record CustomUserDetails(UUID userId,String username,String password,String role,boolean accountNonLocked) implements UserDetails { public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role));} public String getPassword(){return password;} public String getUsername(){return username;} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return accountNonLocked;} public boolean isCredentialsNonExpired(){return true;} public boolean isEnabled(){return true;} }
